import AppKit
import OmniPilotKit

@MainActor
final class PasteboardMonitor {
    static let shared = PasteboardMonitor(history: .shared)

    private static let sensitiveTypeFragments = [
        "concealed", "transient", "autogenerated", "password", "onepassword", "agilebits"
    ]

    private let history: ClipboardHistory
    private let interval: TimeInterval
    private var timer: Timer?
    private var lastChangeCount: Int?

    init(history: ClipboardHistory, interval: TimeInterval = 0.8) {
        self.history = history
        self.interval = interval
    }

    func start() {
        guard timer == nil else { return }
        lastChangeCount = NSPasteboard.general.changeCount

        let timer = Timer(timeInterval: interval, repeats: true) { [weak self] _ in
            Task { @MainActor in self?.checkPasteboard() }
        }
        timer.tolerance = 0.1
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    func stop() {
        timer?.invalidate()
        timer = nil
        lastChangeCount = nil
    }

    /// Writes a recalled item without treating OmniPilot's own write as a new copy.
    func writeToPasteboard(_ text: String) {
        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        guard pasteboard.setString(text, forType: .string) else { return }
        lastChangeCount = pasteboard.changeCount
    }

    private func checkPasteboard() {
        let pasteboard = NSPasteboard.general
        let changeCount = pasteboard.changeCount
        guard changeCount != lastChangeCount else { return }
        lastChangeCount = changeCount

        let types = pasteboard.types ?? []
        guard !containsSensitiveType(types),
              let text = pasteboard.string(forType: .string) else { return }

        history.record(text)
    }

    private func containsSensitiveType(_ types: [NSPasteboard.PasteboardType]) -> Bool {
        types.contains { type in
            let rawValue = type.rawValue.lowercased()
            return Self.sensitiveTypeFragments.contains { rawValue.contains($0) }
        }
    }
}
